TOPICS = [
    dict(slug="percentage-change-vs-percentage-points", title="Percentage Change vs Percentage Points: A Clear Guide", desc="Learn when to use percentage change, percentage points and percentage difference, with worked examples and a practical calculator workflow.", question="Are you comparing a rate, a price, a score or a measurement that changed over time? The first step is to identify whether the number itself changed or whether a percentage rate changed.", formula="Percentage change = (new value − original value) ÷ original value × 100. Percentage-point change = new percentage − original percentage.", example="A conversion rate moving from 12% to 15% rises by 3 percentage points. Relative to the original 12%, the percentage change is 25%.", calc="percentage-change-calculator.html", context="This distinction matters in reports because calling a three-point movement a 3% increase can understate or overstate what happened.", practice="Keep the original baseline visible in a report. A change is not interpretable without knowing the starting period, population and units.", mistakes="The most common mistake is dividing by the new number instead of the original baseline. Another is comparing percentages from different populations or periods without checking that the denominators match.", related=[("Percentage Change Calculator","percentage-change-calculator.html"),("Percentage Difference Calculator","percentage-difference-calculator.html")]),
    dict(slug="average-vs-weighted-average", title="Average vs Weighted Average: Which Method Fits Your Data?", desc="Understand the difference between a simple average and a weighted average, with a worked example and practical checks for calculator results.", question="Two averages can describe the same list of numbers very differently when observations represent different quantities. A class average, portfolio return or product cost often needs weights.", formula="Simple average = sum of values ÷ number of values. Weighted average = sum of (value × weight) ÷ sum of weights.", example="If two projects score 80 and 60 but carry weights of 70% and 30%, the weighted result is 74, not the simple average of 70.", calc="average-calculator.html", context="Averages are summaries, not complete descriptions. Always state what each observation represents and whether a large observation should influence the result more than a small one.", practice="Use weights that describe exposure, quantity, credits or population share. If weights do not add to 100%, make clear whether the calculator normalizes them.", mistakes="Do not average percentages from groups of different sizes without group-size weights. Do not mix monthly and annual figures or use a weight that is already a percentage of a different total.", related=[("Weighted Average Calculator","weighted-average-calculator.html"),("Average Calculator","average-calculator.html")]),
    dict(slug="ratio-and-proportion-solving", title="How to Solve Ratios and Proportions Step by Step", desc="Learn how ratios describe relationships, how to scale a proportion, and how to check a ratio calculation with a real example.", question="Ratios are useful when the relationship between quantities matters more than their individual totals. Recipes, mixtures, maps, staffing and financial comparisons all use ratios.", formula="For a:b = c:d, the cross-products satisfy a × d = b × c. To scale a:b by a factor k, multiply both terms by k.", example="A concrete mix with a cement-to-sand ratio of 1:3 uses 3 buckets of sand for 1 bucket of cement. For 5 buckets of cement, the proportional sand quantity is 15 buckets.", calc="ratio-calculator.html", context="A ratio does not automatically tell you the total quantity. It tells you how quantities relate. Add the terms to find the number of equal parts when distributing a total.", practice="Reduce ratios to a common unit before comparing them. Label whether the ratio is part-to-part or part-to-whole, because those answers are not interchangeable.", mistakes="A frequent error is reversing the order of the terms. Another is using a ratio with incompatible units, such as comparing kilograms with litres without a density assumption.", related=[("Ratio Calculator","ratio-calculator.html"),("Proportion Calculator","proportion-calculator.html")]),
    dict(slug="break-even-analysis-for-small-business", title="Break-Even Analysis for a Small Business", desc="Use fixed costs, variable cost and selling price to estimate break-even units and revenue, with a cautious planning workflow.", question="Break-even analysis asks how many units must be sold before contribution covers fixed costs. It is a planning model, not a promise that demand or price will remain constant.", formula="Contribution per unit = selling price − variable cost. Break-even units = fixed costs ÷ contribution per unit. Break-even revenue = break-even units × selling price.", example="With fixed costs of ₹1,20,000, a price of ₹500 and variable cost of ₹300, contribution is ₹200. Break-even is 600 units and ₹3,00,000 revenue before taxes and financing.", calc="break-even-calculator.html", context="The result is most useful as a sensitivity range. Test a lower price, higher input cost and slower sales volume rather than relying on one optimistic case.", practice="Separate costs that change with each unit from costs that remain within the planning period. Include realistic packaging, payment fees, wastage and delivery costs in variable cost.", mistakes="Do not treat total monthly expenses as fixed if part of them rises with sales. Do not divide by selling price alone; the business breaks even on contribution after variable costs.", related=[("Break-Even Calculator","break-even-calculator.html"),("Contribution Margin Calculator","contribution-margin-calculator.html")]),
    dict(slug="gross-margin-vs-markup", title="Gross Margin vs Markup: Formula, Example and Pricing Use", desc="Gross margin and markup use the same gross profit but different denominators. Learn the formulas and why confusing them causes pricing errors.", question="A product can have a 25% markup and a 20% gross margin at the same time. The difference is not a contradiction; it comes from dividing profit by cost versus selling price.", formula="Gross profit = selling price − cost. Markup = gross profit ÷ cost × 100. Gross margin = gross profit ÷ selling price × 100.", example="A product costing ₹800 and selling for ₹1,000 has ₹200 gross profit. Markup is 25%, while margin is 20%.", calc="gross-margin-calculator.html", context="Margin is commonly used to discuss revenue profitability, while markup is often used to build a selling price from a known cost. State the term whenever you quote a percentage.", practice="When converting a target margin m into a price, price = cost ÷ (1 − m). That is different from multiplying cost by 1 + markup, so label the input clearly.", mistakes="The biggest mistake is applying a target margin as if it were a markup. Also avoid comparing margins before deciding whether costs include freight, discounts, returns and payment charges.", related=[("Gross Margin Calculator","gross-margin-calculator.html"),("Markup Calculator","markup-calculator.html")]),
    dict(slug="stacking-discounts-correctly", title="How to Calculate Stacked Discounts Correctly", desc="Learn why two discounts are usually not added directly, how to calculate the effective discount and how tax and shipping change the final bill.", question="A 20% discount followed by a 10% discount is not a 30% discount on the original price. The second discount applies to the already reduced price.", formula="Final price = original price × (1 − first discount) × (1 − second discount). Effective discount = 1 − product of the remaining-price factors.", example="A ₹10,000 item after 20% and then 10% discount costs ₹7,200. The effective discount is 28%, not 30%.", calc="discount-calculator.html", context="Retail offers may apply discounts to selected items, coupons, shipping or a maximum eligible value. A mathematical result is useful only when the offer terms match the inputs.", practice="Write the order of discounts down. Compare the final payable amount, not only the headline percentage, and check whether GST is calculated before or after the discount.", mistakes="Adding percentages is the common error. Other errors include applying a coupon to the original price twice or forgetting a fixed-amount coupon, shipping fee or minimum order requirement.", related=[("Discount Calculator","discount-calculator.html"),("GST Calculator","gst-calculator.html")]),
    dict(slug="gst-inclusive-and-exclusive-workflow", title="GST Inclusive and Exclusive Prices: A Practical Workflow", desc="A calculation-led guide to adding GST, extracting GST from an inclusive price and checking rounding assumptions.", question="The same invoice can show a taxable value plus GST or a GST-inclusive total. The correct reverse calculation depends on the tax rate, not on subtracting the rate percentage from the total.", formula="Exclusive total = base price × (1 + rate ÷ 100). From an inclusive total, taxable value = inclusive total ÷ (1 + rate ÷ 100); GST = inclusive total − taxable value.", example="At 18% GST, a ₹1,180 inclusive price contains ₹1,000 taxable value and ₹180 GST before invoice rounding.", calc="gst-calculator.html", context="Indian invoices may split GST into CGST and SGST for an intra-state supply or show IGST for an inter-state supply. The calculator is an estimate and does not determine classification or eligibility.", practice="Keep the tax rate, taxable value, place of supply and invoice rounding rule with the calculation. Compare the result with the supplier's tax invoice.", mistakes="Do not calculate reverse GST as total × 18%. That gives the wrong tax because the tax is already included in the total.", related=[("GST Calculator","gst-calculator.html"),("GST Inclusive vs Exclusive Guide","gst-inclusive-exclusive-calculation-guide.html")]),
    dict(slug="contribution-margin-for-decisions", title="Contribution Margin: A Better Short-Term Pricing Signal", desc="Learn how contribution margin supports product, promotion and capacity decisions without confusing it with net profit.", question="Contribution margin shows how much revenue remains after variable costs to cover fixed costs and profit. It is valuable for short-term decisions when fixed costs do not change.", formula="Contribution margin per unit = selling price − variable cost. Contribution margin ratio = contribution ÷ selling price × 100.", example="At ₹250 price and ₹150 variable cost, contribution is ₹100 per unit and the ratio is 40%. Selling 1,000 units contributes ₹1,00,000 before fixed costs.", calc="contribution-margin-calculator.html", context="A high ratio does not guarantee a profitable business. Rent, salaries, depreciation, interest, tax, returns and idle capacity still matter.", practice="Build a contribution view by product and channel. Include variable commissions, payment fees, packaging, incremental labour and expected returns where they change with each sale.", mistakes="Do not put fixed monthly rent into variable cost just because it is paid every month. Do not use accounting gross profit and contribution margin interchangeably without reconciling cost classifications.", related=[("Contribution Margin Calculator","contribution-margin-calculator.html"),("Break-Even Calculator","break-even-calculator.html")]),
    dict(slug="cash-conversion-cycle-explained", title="Cash Conversion Cycle: Inventory, Receivables and Payables", desc="Understand the cash conversion cycle and how inventory days, receivable days and payable days affect working capital.", question="A profitable business can still feel short of cash when money is tied up in inventory or unpaid invoices. The cash conversion cycle describes that timing gap.", formula="CCC = inventory days + receivable days − payable days. Inventory days often use average inventory ÷ cost of goods sold × days.", example="If inventory takes 45 days to sell, customers pay in 30 days and suppliers allow 20 days, the cycle is 55 days.", calc="cash-conversion-cycle-calculator.html", context="The calculation is a management indicator, not a complete cash-flow forecast. Seasonality, prepayments, tax dates, deposits and one-off purchases can change actual cash needs.", practice="Use average balances where possible and compare the same period. Review the cycle by customer, product and supplier rather than relying only on a company-wide average.", mistakes="Using revenue instead of cost of goods sold for inventory days can distort the result. Another error is treating payment terms as actual payment behaviour.", related=[("Cash Conversion Cycle Calculator","cash-conversion-cycle-calculator.html"),("Inventory Turnover Calculator","inventory-turnover-calculator.html")]),
    dict(slug="inventory-turnover-and-days", title="Inventory Turnover and Inventory Days: How to Read the Result", desc="Learn how inventory turnover connects cost of goods sold with average stock and how to interpret turnover without overstocking or stockouts.", question="Inventory turnover measures how often average stock is sold or used during a period. Inventory days converts that frequency into an easier time-based view.", formula="Inventory turnover = cost of goods sold ÷ average inventory. Inventory days = days in period ÷ turnover.", example="COGS of ₹24 lakh and average inventory of ₹4 lakh produce turnover of 6 times. Using a 365-day year, inventory days are about 60.8 days.", calc="inventory-turnover-calculator.html", context="A high turnover may indicate efficient stock management, but it may also mean insufficient safety stock or lost sales. A low turnover may reflect slow products, seasonal stock or deliberate bulk buying.", practice="Compare similar products and periods. Adjust the story for demand seasonality, stockouts, product life cycle and accounting valuation method.", mistakes="Do not compare one company's turnover with another without checking industry, product mix and COGS treatment. Do not use ending inventory alone when average inventory is available.", related=[("Inventory Turnover Calculator","inventory-turnover-calculator.html"),("Reorder Point Calculator","reorder-point-calculator.html")]),
    dict(slug="reorder-point-and-safety-stock", title="Reorder Point and Safety Stock: A Practical Inventory Guide", desc="Calculate when to reorder stock using demand, lead time and safety stock, then test what happens when supply or demand changes.", question="The reorder point is the stock level that triggers a replenishment order. It is designed to cover expected demand during supplier lead time and, where used, a safety buffer.", formula="Basic reorder point = average demand during lead time + safety stock. If demand is daily, multiply daily demand by lead-time days.", example="At 40 units per day, 7-day lead time and 80 units of safety stock, the reorder point is 360 units.", calc="reorder-point-calculator.html", context="Safety stock is not a universal percentage. It should reflect demand variability, supplier reliability, service level and the cost of a stockout.", practice="Record the unit and time basis for every input. Review lead time using actual receiving history, not only the supplier's best-case promise.", mistakes="Mixing weekly demand with daily lead time produces a silent scale error. Another mistake is treating reorder point as order quantity; they answer different questions.", related=[("Reorder Point Calculator","reorder-point-calculator.html"),("Inventory Turnover Calculator","inventory-turnover-calculator.html")]),
    dict(slug="economic-order-quantity-eoq", title="EOQ: When Economic Order Quantity Helps Inventory Planning", desc="Understand the economic order quantity model, its assumptions and the situations where a simple EOQ estimate should not be used alone.", question="EOQ balances ordering cost against holding cost under a simplified demand model. It is a starting point for purchase planning, not an automatic purchase instruction.", formula="EOQ = square root of (2 × annual demand × ordering cost ÷ annual holding cost per unit).", example="For annual demand of 12,000 units, ordering cost ₹500 and annual holding cost ₹20 per unit, EOQ is approximately 775 units.", calc="eoq-calculator-economic-order-quantity.html", context="The model assumes relatively stable demand, known costs, replenishment without shortage and no complex quantity discounts. Real procurement may need minimum order quantities, shelf life and supplier constraints.", practice="Run a sensitivity check. If holding cost doubles or demand changes, the suggested order quantity changes; this is why the result should be reviewed periodically.", mistakes="Do not enter a holding-cost percentage as if it were a rupee amount. Do not interpret EOQ as safety stock, reorder point or a forecast of demand.", related=[("EOQ Calculator","eoq-calculator-economic-order-quantity.html"),("Reorder Point Calculator","reorder-point-calculator.html")]),
    dict(slug="capacity-utilization-and-idle-time", title="Capacity Utilization: Measure Output Against Available Capacity", desc="Learn how capacity utilization is calculated, how idle time affects the result and why a high percentage is not always better.", question="Capacity utilization compares actual output with practical or maximum available capacity. The denominator must be defined before the percentage is meaningful.", formula="Capacity utilization = actual output ÷ available capacity × 100.", example="A line capable of 8,000 good units per month produces 6,400 good units, giving 80% utilization. If planned maintenance reduces practical capacity to 7,200, utilization is 88.9% against that denominator.", calc="capacity-utilization-calculator.html", context="Maximum theoretical capacity and practical capacity answer different questions. Practical capacity allows for maintenance, breaks, changeovers, quality checks and normal downtime.", practice="Report good output separately from total processed output. A line can appear busy while producing scrap, rework or the wrong mix of products.", mistakes="Changing the denominator from month to month hides the trend. Another error is treating utilization as overall equipment effectiveness; availability, performance and quality may tell a different story.", related=[("Capacity Utilization Calculator","capacity-utilization-calculator.html"),("Takt Time Calculator","takt-time-calculator.html")]),
    dict(slug="takt-time-vs-cycle-time", title="Takt Time vs Cycle Time: How Production Pace Is Compared", desc="Understand the difference between customer-demand pace and actual process time, with a line-balancing example.", question="Takt time describes the pace needed to meet demand. Cycle time describes how long a process actually takes for one unit. Comparing them helps identify capacity risk.", formula="Takt time = available production time ÷ customer demand. For a process to keep up, cycle time should generally be at or below takt time.", example="With 420 available minutes and demand of 210 units, takt time is 2 minutes per unit. A workstation cycle time of 2.4 minutes cannot meet that pace without additional capacity or balancing.", calc="takt-time-calculator.html", context="Available time must exclude planned breaks, maintenance and other unavailable periods. Demand should match the same shift, product family and quality definition.", practice="Measure actual cycle time over a representative sample. Use the result to discuss staffing, parallel stations, changeover reduction and bottlenecks rather than blaming one operator.", mistakes="Do not call takt time the machine's speed. Do not divide total calendar time by demand when the process runs only during scheduled hours.", related=[("Takt Time Calculator","takt-time-calculator.html"),("Cycle Time Calculator","cycle-time-calculator.html")]),
    dict(slug="process-capability-cp-cpk-basics", title="Cp and Cpk: A Practical Process Capability Explanation", desc="Learn what Cp and Cpk compare, how specification limits and variation affect the result, and why a capability index needs stable data.", question="Process capability indices compare process spread and centering with specification limits. They are useful only when the measurement system and process are appropriate for the question.", formula="Cp = (USL − LSL) ÷ (6σ). Cpk is the smaller of (USL − mean) ÷ (3σ) and (mean − LSL) ÷ (3σ).", example="With USL 10.6, LSL 9.4, mean 10.1 and σ 0.1, Cp is 2.0 while Cpk is about 1.67 because the mean is not exactly centered.", calc="process-capability-index-calculator.html", context="A high index does not prove that the process is stable, the specifications are correct or the gauge is reliable. Capability is a statistical estimate tied to the sample and assumptions.", practice="Plot the observations, check control behaviour and confirm that the units and specification limits refer to the same characteristic. Keep subgrouping and sampling notes.", mistakes="Using a changing process, mixing lots or using a biased measurement system can make the index misleading. Cp alone can hide an off-centre mean.", related=[("Process Capability Index Calculator","process-capability-index-calculator.html"),("Standard Deviation Calculator","standard-deviation-calculator.html")]),
    dict(slug="yield-loss-and-scrap-rate", title="Yield, Scrap Rate and First-Pass Quality: Three Useful Views", desc="Compare good output with input, scrap and rework using yield and scrap calculations that keep production reporting consistent.", question="Yield and scrap rate describe different sides of the same production story. The denominator and treatment of rework must be stated to avoid misleading comparisons.", formula="Yield = good output ÷ input × 100. Scrap rate = scrap quantity ÷ input quantity × 100. First-pass yield excludes units that required rework from the first-pass good count.", example="From 1,000 input units, 940 pass without rework, 40 pass after rework and 20 are scrapped. Final yield is 98%, but first-pass yield is 94% and scrap rate is 2%.", calc="actual-yield-calculator.html", context="A high final yield can hide rework labour, inspection time and delayed delivery. Use first-pass yield when the aim is to understand how often the process produces a right-first-time unit.", practice="Define whether returns, startup waste and rework are included. Use consistent lot boundaries and record the reason for loss when improvement action is expected.", mistakes="Do not divide scrap by good output. Do not count reworked units as first-pass good units, and do not compare yield figures with different definitions.", related=[("Actual Yield Calculator","actual-yield-calculator.html"),("Theoretical Yield Calculator","theoretical-yield-calculator.html")]),
    dict(slug="material-removal-rate-mrr", title="Material Removal Rate: Estimating Machining Productivity", desc="Learn how material removal rate connects cutting dimensions and feed rate, and why machine limits and tool life still matter.", question="Material removal rate estimates how quickly a cutting operation removes material. It can help compare setups, but it is not a complete measure of machining cost or quality.", formula="For a simplified milling estimate, MRR = width of cut × depth of cut × feed rate, using consistent units.", example="A 20 mm width, 2 mm depth and 300 mm/min feed produce 12,000 cubic millimetres per minute in the simplified model.", calc="material-removal-rate-calculator.html", context="Actual MRR depends on tool geometry, engagement, material, spindle power, coolant, chip evacuation and machine rigidity. The formula should be checked against approved cutting data.", practice="Convert all dimensions to one unit before multiplying. Compare MRR with surface finish, tool wear, deflection and safe operating limits.", mistakes="Mixing mm with inches creates a large error. Another mistake is treating a higher theoretical MRR as automatically better when it causes tool failure or poor surface quality.", related=[("Material Removal Rate Calculator","material-removal-rate-calculator.html"),("Spindle Speed Calculator","spindle-speed-calculator.html")]),
    dict(slug="electricity-cost-from-power-and-time", title="How to Estimate Electricity Cost from Power and Usage Time", desc="Calculate energy use from power and operating hours, then separate a simple consumption estimate from a complete electricity bill.", question="A device's power rating becomes an energy cost only after it is combined with operating time and a tariff. The rating may describe maximum or nominal draw, not actual average use.", formula="Energy in kWh = power in kW × operating hours. Estimated energy cost = kWh × tariff per kWh.", example="A 1.5 kW appliance used for 4 hours per day over 30 days consumes 180 kWh. At ₹8 per kWh, the energy-only estimate is ₹1,440.", calc="electricity-bill-calculator.html", context="A real bill may include fixed charges, slabs, taxes, fuel adjustments, subsidies, demand charges and meter-specific rules. Treat the result as a consumption scenario.", practice="Measure actual use where possible and distinguish standby, cycling and full-load operation. Use the tariff applicable to the connection and billing period.", mistakes="Do not multiply watts by hours without dividing watts by 1,000 to get kilowatts. Do not assume the appliance runs at full rated power for the entire time.", related=[("Electricity Bill Calculator","electricity-bill-calculator.html"),("Power Converter","power-converter.html")]),
    dict(slug="fuel-cost-trip-planning", title="Fuel Cost for a Trip: Distance, Mileage and Price", desc="Estimate trip fuel cost, compare vehicle efficiency and understand why traffic, payload and route conditions change the final result.", question="Trip fuel cost is a scenario estimate based on distance, efficiency and fuel price. It is most useful when you test realistic ranges rather than one precise number.", formula="Fuel used = distance ÷ mileage. Fuel cost = fuel used × price per unit.", example="A 360 km trip at 18 km/L uses 20 litres. At ₹105 per litre, the estimated fuel cost is ₹2,100 before tolls, detours and idling.", calc="fuel-cost-calculator.html", context="Mileage can vary with speed, tyre pressure, traffic, terrain, air conditioning, payload and driving style. Electric vehicles need a different energy and charging-cost model.", practice="Add a return trip, local driving and a reasonable detour buffer. Keep tolls, parking and maintenance separate if comparing total trip cost.", mistakes="Using the vehicle's brochure mileage as a guarantee is risky. Make sure distance and mileage use compatible units and do not mix a one-way distance with a round-trip assumption.", related=[("Fuel Cost Calculator","fuel-cost-calculator.html"),("Mileage Calculator","mileage-calculator.html")]),
    dict(slug="bmi-and-health-context", title="BMI Calculation: What the Number Can and Cannot Tell You", desc="Learn how BMI is calculated, how units are converted and why the result should not be treated as a diagnosis.", question="BMI is a screening ratio using height and weight. It can provide a starting point for discussion but does not directly measure body fat, fitness, muscle or health risk for every person.", formula="BMI = weight in kilograms ÷ height in metres squared.", example="A person weighing 70 kg and measuring 1.75 m has BMI 70 ÷ 1.75², approximately 22.9.", calc="bmi-calculator.html", context="Age, sex, muscle mass, pregnancy, ethnicity, medical conditions and measurement error can affect how a BMI value should be interpreted. Categories are screening conventions, not a personal diagnosis.", practice="Use consistent units and a measured height. If the result concerns a health decision, discuss it with a qualified clinician who can consider waist measurement, history and other indicators.", mistakes="Do not square height in centimetres without converting to metres. Do not treat one reading as a trend or use BMI to judge an individual without context.", related=[("BMI Calculator","bmi-calculator.html"),("Calorie Calculator","calorie-calculator.html")]),
    dict(slug="age-calculation-and-date-boundaries", title="Age Calculation: Completed Years, Birthdays and Date Boundaries", desc="Understand how age in completed years differs from an approximate year difference and how leap-day birthdays affect date calculations.", question="Age is usually expressed in completed years, but some forms and eligibility rules use a specific cut-off date. The same two dates can produce different answers under different conventions.", formula="Completed age increases on the birthday; an approximate year difference may simply subtract calendar years and can be off by one.", example="Someone born on 15 August 2000 is 26 on 15 August 2026, but is still 25 on 14 August 2026.", calc="age-calculator.html", context="For an application, exam, insurance or legal requirement, use the rule and cut-off date stated by the authority. A general age calculator cannot decide which rule applies.", practice="Enter dates in an unambiguous day-month-year format and check the time zone if the birth date or cut-off occurs near midnight.", mistakes="Subtracting years without checking whether the birthday has occurred is the most common error. Another is treating an approximate age as an exact duration in days.", related=[("Age Calculator","age-calculator.html"),("Date Difference Calculator","date-difference-calculator.html")]),
    dict(slug="date-difference-working-days", title="Date Difference vs Working Days: Choose the Right Count", desc="Learn the difference between elapsed calendar days, inclusive dates and working-day counts with a practical planning example.", question="A date difference can mean the number of midnights crossed, the number of calendar dates including both endpoints or the number of working days. State the convention before using the result.", formula="Elapsed days depend on the endpoint convention. Working days exclude weekends and may also exclude a supplied holiday list.", example="A Monday-to-Friday period can be 4 elapsed days when counting gaps, 5 inclusive calendar dates and 5 working days before holidays are removed.", calc="date-difference-calculator.html", context="Payroll, project schedules, service-level agreements and legal deadlines can use different counting rules. The calculator helps explore dates; the governing document controls.", practice="Record start date, end date, inclusivity, weekend pattern and holidays. Recheck when a daylight-saving or time-zone boundary matters for timestamps.", mistakes="Counting both endpoints by habit can create an extra day. Do not assume all weekends are Saturday and Sunday or that a public holiday list is universal.", related=[("Date Difference Calculator","date-difference-calculator.html"),("Working Days Calculator","working-days-calculator.html")]),
    dict(slug="area-conversion-for-land-and-projects", title="Area Conversion for Land, Rooms and Project Estimates", desc="Convert area units consistently and avoid the common mistake of converting length when the quantity is already an area.", question="Area conversion uses squared conversion factors. A length conversion cannot be copied unchanged into an area calculation because both dimensions change.", formula="If 1 unit of length equals k units, 1 square unit equals k² square units. Area of a rectangle = length × width.", example="A 10 m by 8 m room has 80 m². Since 1 m² is 10.7639 square feet, the same area is about 861.1 ft².", calc="area-converter.html", context="Land records may use local units whose size varies by region. For a purchase, construction quantity or legal record, verify the definition with the relevant local authority or document.", practice="Keep the original unit, converted unit and precision visible. Round only after the conversion so early rounding does not accumulate.", mistakes="Using 10.7639 as a length factor for a square-foot dimension is wrong in some contexts. Confusing perimeter with area is another common planning error.", related=[("Area Converter","area-converter.html"),("Land Unit Converter","land-unit-converter-calculator.html")]),
    dict(slug="concrete-volume-estimate", title="Concrete Volume Estimate: Dimensions, Waste and Units", desc="Estimate concrete volume from length, width and depth, convert units and add a cautious allowance without replacing an engineering takeoff.", question="Concrete volume starts with geometry. The quantity ordered may then need allowance for uneven subgrade, formwork losses, spillage and the supplier's minimum load.", formula="Rectangular volume = length × width × depth. Convert the result to the supplier's unit, commonly cubic metres or cubic yards.", example="A slab 6 m long, 4 m wide and 0.1 m thick has geometric volume 2.4 m³. A project may order a documented allowance above that quantity after site review.", calc="concrete-calculator.html", context="The estimate does not select concrete grade, reinforcement, cover, placement method or structural design. Those decisions belong to the approved drawing and qualified professional.", practice="Measure actual thickness at several points and separate slabs, footings, columns and steps. Keep waste allowance explicit instead of hiding it in a rounded dimension.", mistakes="Using centimetres with metres creates a scale error. Do not add waste twice or assume every irregular shape is a simple rectangle.", related=[("Concrete Calculator","concrete-calculator.html"),("Concrete Column Calculator","concrete-column-calculator.html")]),
    dict(slug="roof-pitch-and-rise-run", title="Roof Pitch: Rise, Run, Angle and Material Planning", desc="Understand roof pitch as a rise-to-run relationship, convert it to an angle and see why a pitch estimate is not a construction drawing.", question="Roof pitch describes how much a roof rises over a horizontal run. It helps communicate slope, but roof area and structural design require more dimensions and specifications.", formula="Pitch ratio = rise ÷ run. Angle in degrees = arctangent(rise ÷ run). For a symmetrical roof, each side's slope length can be estimated from the rise and run using Pythagoras.", example="A rise of 4 units over a 12-unit run is a 4:12 pitch. The angle is about 18.4 degrees before considering measurement and construction details.", calc="roof-pitch-calculator.html", context="Roofing material overlap, eaves, hips, valleys, penetrations and local weather requirements can increase material area beyond the simple slope rectangle.", practice="Measure the horizontal run rather than the sloping face when using a pitch ratio. Confirm the convention with the roofer or drawing set.", mistakes="Confusing total roof width with one-side run can double or halve the result. Do not use a pitch calculator to approve structural safety or drainage design.", related=[("Roof Pitch Calculator","roof-pitch-calculator.html"),("Roofing Calculator","roofing-calculator.html")]),
    dict(slug="paint-coverage-and-coats", title="Paint Coverage: Estimate Litres, Coats and Surface Area", desc="Estimate paint quantity from surface area and coverage, then account for coats, porosity and practical waste.", question="Paint coverage is an average spread rate. Actual use changes with surface texture, colour change, application method and the number of coats required.", formula="Paint quantity = surface area × number of coats ÷ coverage per litre. Add a documented allowance for losses and touch-ups.", example="For 80 m², two coats and coverage of 10 m² per litre, the geometric estimate is 16 litres before waste and product-pack rounding.", calc="paint-calculator.html", context="Coverage printed on a tin is usually a test or ideal estimate. Primers, porous plaster, rough masonry and strong colour changes may require a different system.", practice="Measure doors and windows separately, follow the product data sheet and buy compatible batches when colour consistency matters.", mistakes="Forgetting the second coat is common. Another error is mixing square metres with square feet or treating a coverage figure as guaranteed regardless of surface.", related=[("Paint Calculator","paint-calculator.html"),("Area Converter","area-converter.html")]),
    dict(slug="round-pool-volume-and-water", title="Round Pool Volume: Diameter, Depth and Water Quantity", desc="Calculate the approximate volume of a round pool and understand why a filled pool may not behave like a perfect cylinder.", question="A circular pool volume depends on radius and average water depth. Sloped floors, steps, freeboard and irregular shapes mean the geometric result is an estimate.", formula="Cylinder volume = π × radius² × average depth. Convert cubic metres to litres by multiplying by 1,000.", example="A pool 4 m in diameter with 1.4 m average depth has radius 2 m and volume about 17.6 m³, or roughly 17,600 litres.", calc="round-pool-volume-calculator.html", context="Water treatment dosage, heating energy and pump sizing may use different operating volumes. Follow equipment and chemical product instructions rather than applying a generic estimate blindly.", practice="Use average depth for a sloped floor and subtract steps or ledges when they are material. Recheck after installation using the actual fill level.", mistakes="Using diameter as radius doubles the radius and quadruples the radius-squared part of the formula. Do not confuse water volume with outside excavation or liner area.", related=[("Round Pool Volume Calculator","round-pool-volume-calculator.html"),("Pool Salt Calculator","pool-salt-calculator.html")]),
    dict(slug="unit-conversion-and-significant-digits", title="Unit Conversion and Significant Digits: Keep Results Honest", desc="Learn how to convert units without hiding measurement uncertainty and how to choose sensible rounding for calculator outputs.", question="A calculator can display many decimal places even when the original measurement is approximate. Unit conversion should preserve meaning, not create false precision.", formula="Converted value = original value × conversion factor. For compound units, convert each dimension or use a factor with the correct numerator and denominator.", example="If a measured length is 2.0 m, converting it to 6.5617 ft does not mean the measurement is known to five decimal places; a rounded presentation may be more honest.", calc="unit-converter.html", context="Engineering, laboratory, finance and everyday estimates have different precision needs. Use the source measurement uncertainty and the decision's tolerance to choose display precision.", practice="Keep full precision internally, round the displayed result, and label the unit. Record the factor or standard used when conversions must be audited.", mistakes="Mixing mass and force, volume and mass, or decimal and binary prefixes can produce a plausible but wrong answer. Always check dimensional compatibility.", related=[("Unit Converter","unit-converter.html"),("Significant Figures Calculator","significant-figures-calculator.html")]),
]

CSS = """<style>:root{--ink:#172638;--muted:#5b6b7b;--navy:#101c2c;--gold:#d8bd82;--line:#dfe5eb;--paper:#f4f6f8}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.75 system-ui,-apple-system,"Segoe UI",sans-serif}.wrap{width:min(900px,92%);margin:auto}main{padding:28px 0 48px}.crumb{font-size:.9rem;color:var(--muted)}h1{font-size:clamp(2rem,5vw,3rem);line-height:1.15;margin:.5rem 0 1rem}h2{font-size:1.45rem;line-height:1.25;margin:1.8rem 0 .7rem}p,li{color:#354658}.muted{color:var(--muted)}.callout{background:#eef3f7;border-left:4px solid var(--gold);padding:14px 17px;border-radius:7px;margin:18px 0}.formula{padding:14px;background:#edf3f7;border-radius:8px;overflow-wrap:anywhere}.related{background:#fff;border:1px solid var(--line);border-radius:12px;padding:18px;margin:24px 0}.related li{margin:8px 0}.faq details{background:#fff;border:1px solid var(--line);border-radius:9px;padding:13px 16px;margin:10px 0}.faq summary{font-weight:750;cursor:pointer}a{color:#174d79}</style>"""

def article_html(t):
    url = f"https://friendlycalculator.in/blog/{t['slug']}.html"
    related_links = ''.join(f'<li><a href="/calculators/{slug}">{escape(name)}</a></li>' for name, slug in t['related'])
    faq = [
        (f"What is the main formula for {t['title'].split(':')[0]}?", t['formula'] + " Use the units and baseline stated by the calculator."),
        ("Can this calculator replace a professional or official result?", "No. It is a transparent planning estimate. Product terms, official rules, measurements and qualified review take priority when the decision is regulated, safety-critical or financially important."),
        ("How should I improve the estimate?", "Change one assumption at a time, keep the input units visible, compare a low and high case, and save the assumptions beside the result."),
    ]
    faq_html=''.join(f'<details><summary>{escape(q)}</summary><p>{escape(a)}</p></details>' for q,a in faq)
    body = f'''<p>{escape(t['question'])} {escape(t['context'])}</p>
<h2>What the calculation measures</h2><p>{escape(t['context'])} A useful estimate begins by naming the quantity, the period or physical boundary, and the unit. That sounds simple, but many mistakes come from entering a correct number into the wrong definition. Before opening the tool, write down what is included and excluded. If the input is a rate, identify its denominator. If it is a cost, decide whether tax, fees, wastage, interest or delivery are included.</p>
<h2>The formula and the baseline</h2><div class="formula">{escape(t['formula'])}</div><p>The formula is a model of the relationship between the inputs. It is not a hidden guarantee about a bank, supplier, machine, health outcome or government assessment. Keep the original baseline visible because a result without its baseline can be difficult to audit. When units are changed, convert first and round only after the main calculation.</p>
<h2>Worked example</h2><p>{escape(t['example'])} This example is intentionally limited: it demonstrates the arithmetic, not a recommendation. In a real decision, replace the illustrative values with documented figures and record the date, source and assumptions used.</p>
<h2>How to use the calculator responsibly</h2><ol><li>Choose the closest tool and read the input labels before entering values.</li><li>Use consistent units and check whether the calculator expects a total, a rate, an average or a per-unit figure.</li><li>Run a base case, a cautious case and a favourable case. A range usually communicates uncertainty better than a single number.</li><li>Read the result alongside the formula and limitations. Save the assumptions if the estimate will be shared.</li></ol>
<h2>Interpretation and decision use</h2><p>{escape(t['practice'])} Use the output to ask a better question: what changes if demand falls, the input cost rises, the time period changes, or the measurement is off by a reasonable amount? Sensitivity is often more valuable than a false impression of precision. If two scenarios are close, the decision may depend on liquidity, safety, quality, tax treatment, service level or contractual terms that are outside this simple calculation.</p>
<h2>Common mistakes to avoid</h2><p>{escape(t['mistakes'])} Also check whether the calculator's denominator, date range and rounding convention match the document or process you are comparing. A result can be mathematically correct and still answer a different question from the one the user intended.</p>
<h2>What this estimate does not decide</h2><p>{escape(t['context'])} For tax, lending, investment, medical, legal, structural, electrical or industrial safety decisions, confirm the current rule or specification with the responsible official source or a qualified professional. Friendly Calculator provides browser-based estimates and general explanations; it does not issue approvals, guarantees, diagnoses or regulated advice.</p>
<h2>Try the related tool</h2><p>Open the <a href="/calculators/{t['calc']}">{escape(t['title'].split(':')[0])} Calculator</a> and test your own assumptions. Compare the result with the related tools below when the decision involves more than one quantity.</p>
<section class="related"><h2>Related calculators</h2><ul>{related_links}</ul><p><a href="/blog/">Browse all calculator guides</a> · <a href="/calculator/methodology.html">Read our calculation methodology</a></p></section>
<section class="faq"><h2>Frequently asked questions</h2>{faq_html}</section>'''
    ld = '{"@context":"https://schema.org","@type":"Article","headline":'+repr(t['title'])
    # JSON is written safely using json.dumps below in the final assembly.
    import json
    schema=json.dumps({"@context":"https://schema.org","@type":"Article","headline":t['title'],"description":t['desc'],"inLanguage":"en-IN","datePublished":"2026-11-21","dateModified":"2026-11-21","author":{"@type":"Organization","name":"Friendly Calculator","url":"https://friendlycalculator.in/calculator/about.html"},"publisher":{"@type":"Organization","name":"Friendly Calculator","url":"https://friendlycalculator.in/"},"mainEntityOfPage":url}, ensure_ascii=False)
    crumbs=json.dumps({"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://friendlycalculator.in/"},{"@type":"ListItem","position":2,"name":"Blog","item":"https://friendlycalculator.in/blog/"},{"@type":"ListItem","position":3,"name":t['title'],"item":url}]}, ensure_ascii=False)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(t['title'])} | Friendly Calculator</title><meta name="description" content="{escape(t['desc'])}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{url}"><meta property="og:type" content="article"><meta property="og:site_name" content="Friendly Calculator"><meta property="og:title" content="{escape(t['title'])}"><meta property="og:description" content="{escape(t['desc'])}"><meta property="og:url" content="{url}"><meta property="og:image" content="https://friendlycalculator.in/og-friendly-calculator.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(t['title'])}"><meta name="twitter:description" content="{escape(t['desc'])}"><meta name="twitter:image" content="https://friendlycalculator.in/og-friendly-calculator.png"><link rel="icon" href="/favicon-96.png" type="image/png"><link rel="stylesheet" href="/assets/site-shell.css">{CSS}<script type="application/ld+json">{schema}</script><script type="application/ld+json">{crumbs}</script><script defer src="/assets/site-shell.js"></script></head><body><main class="wrap"><p class="crumb"><a href="/">Home</a> / <a href="/blog/">Blog</a> / {escape(t['title'])}</p><h1>{escape(t['title'])}</h1><p class="muted">Original calculator guide · Published {TODAY}</p>{body}</main></body></html>'''

if __name__ == '__main__':
    for t in TOPICS:
        (BLOG / f"{t['slug']}.html").write_text(article_html(t), encoding='utf-8')
